using UnityEngine; using UnityEngine.SceneManagement; using System.IO; using System;
public class LoadMapGUI:GUIScreen{
 string[] saves;Vector2 scroll;void Start(){Refresh();}void Refresh(){saves=InfiniteWorldSave.GetWorldNames();}
 void OnGUI(){VoxelBoxUI.BeginResponsive();VoxelBoxUI.MenuBackground();VoxelBoxUI.Backdrop(.24f);Rect r=VoxelBoxUI.Safe(1080,810,45);GUILayout.BeginArea(r,VoxelBoxUI.Panel);GUILayout.Label("▣  WELT LADEN",VoxelBoxUI.Header);GUILayout.Label("Gespeicherte Welten  •  "+InfiniteWorldSave.SaveDirectory,VoxelBoxUI.Small);GUILayout.Space(12);scroll=GUILayout.BeginScrollView(scroll);
 if(saves!=null&&saves.Length>0)foreach(string n in saves)DrawSave(n);else {GUILayout.Space(80);GUILayout.Label("NOCH KEINE WELTEN GESPEICHERT",VoxelBoxUI.Header);GUILayout.Label("Speichere eine Welt im Pause-Menü. Sie erscheint anschließend automatisch hier.",VoxelBoxUI.Label);}GUILayout.EndScrollView();GUILayout.Space(10);GUILayout.BeginHorizontal();if(GUILayout.Button("↻  AKTUALISIEREN",VoxelBoxUI.Button,GUILayout.Height(44)))Refresh();if(GUILayout.Button("▤  SAVEGAME-ORDNER",VoxelBoxUI.Button,GUILayout.Height(44)))InfiniteWorldSave.OpenSaveDirectory();if(GUILayout.Button("←  ZURÜCK",VoxelBoxUI.Button,GUILayout.Height(44)))SetScreen<MainMenuGUI>();GUILayout.EndHorizontal();GUILayout.EndArea();VoxelBoxUI.EndResponsive();}
 void DrawSave(string n){string path=InfiniteWorldSave.PathFor(n);FileInfo fi=null;try{fi=new FileInfo(path);}catch{} InfiniteWorldSave.WorldType wt;bool hasType=InfiniteWorldSave.TryReadWorldType(n,out wt);GUILayout.BeginVertical(VoxelBoxUI.Card);GUILayout.BeginHorizontal();GUILayout.BeginVertical();GUILayout.Label(n,VoxelBoxUI.Header);string meta=(hasType?(wt==InfiniteWorldSave.WorldType.Tanviir?"TANVIIR":wt==InfiniteWorldSave.WorldType.Wolkenstadt?"WOLKENSTADT":wt==InfiniteWorldSave.WorldType.ImperialCity?"IMPERIAL CITY":"INSELWELT"):"WELT");if(fi!=null&&fi.Exists)meta+="  •  "+fi.LastWriteTime.ToString("dd.MM.yyyy  HH:mm")+"  •  "+FormatSize(fi.Length);GUILayout.Label(meta,VoxelBoxUI.Small);GUILayout.EndVertical();GUILayout.FlexibleSpace();if(GUILayout.Button("▶  LADEN",VoxelBoxUI.Button,GUILayout.Width(180),GUILayout.Height(48))){InfiniteWorldSave.RequestLoad(n);SceneManager.LoadScene("Game");}GUILayout.EndHorizontal();GUILayout.EndVertical();GUILayout.Space(6);}
 string FormatSize(long b){if(b>1024L*1024L)return (b/(1024f*1024f)).ToString("0.0")+" MB";if(b>1024)return (b/1024f).ToString("0.0")+" KB";return b+" B";}
}
